import pandas as pd
from pathlib import Path
import json, numpy as np

csv_path = Path('/app/benchmark/data.csv')
html_path = Path('/app/output/final_report.html')

df = pd.read_csv(csv_path)
df['Date'] = pd.to_datetime(df['Date'])
df = df.sort_values('Date').reset_index(drop=True)
df['Price'] = df['Crude_Oil_Price'].astype(float)

df['MoM_abs'] = df['Price'].diff()
df['MoM_pct'] = df['Price'].pct_change()*100
df['YoY_pct'] = df['Price'].pct_change(12)*100

def decade_label(y):
    d = (y//10)*10
    return f"{d}s"

df['Decade'] = df['Date'].dt.year.apply(decade_label)

first_date, last_date = df['Date'].iloc[0], df['Date'].iloc[-1]
first_price, last_price = df['Price'].iloc[0], df['Price'].iloc[-1]
years = (last_date - first_date).days / 365.2425
cagr = (last_price/first_price)**(1/years)-1

overall_min = df['Price'].min(); overall_max = df['Price'].max(); price_range = overall_max-overall_min
std_all = df['Price'].std(ddof=1)

mom_idx = df['MoM_abs'].abs().idxmax()
max_mom_abs = df.loc[mom_idx, 'MoM_abs']
max_mom_pct = df.loc[mom_idx, 'MoM_pct']
max_mom_date = df.loc[mom_idx, 'Date']

decade_stats = df.groupby('Decade').agg(
    mean_price=('Price','mean'),
    median_price=('Price','median'),
    std_price=('Price','std'),
    min_price=('Price','min'),
    max_price=('Price','max'),
    mom_vol=('MoM_pct', lambda s: s.std(ddof=1))
).reset_index()

highest_decade = decade_stats.sort_values('mean_price', ascending=False).iloc[0]

top_shocks = df.dropna(subset=['MoM_abs']).copy()
top_shocks = top_shocks.reindex(top_shocks['MoM_abs'].abs().sort_values(ascending=False).index).head(10)

desc = df['Price'].describe(percentiles=[0.1,0.25,0.5,0.75,0.9])

payload = {
  'meta': {
    'rows': int(len(df)),
    'start': first_date.strftime('%Y-%m'),
    'end': last_date.strftime('%Y-%m'),
    'first_price': round(first_price,2),
    'last_price': round(last_price,2)
  },
  'kpis': [
    {'label':'Overall Price Range','value':f"${price_range:,.2f}",'note':f"Min ${overall_min:.2f} to Max ${overall_max:.2f}"},
    {'label':'Average Annual Growth Rate (CAGR)','value':f"{cagr*100:.2f}%",'note':f"{first_date.strftime('%Y-%m')} to {last_date.strftime('%Y-%m')}"},
    {'label':'Maximum Month-over-Month Change','value':f"${max_mom_abs:+.2f}",'note':f"{max_mom_pct:+.2f}% in {max_mom_date.strftime('%Y-%m')}"},
    {'label':'Decade with Highest Average Price','value':str(highest_decade['Decade']),'note':f"Mean ${highest_decade['mean_price']:.2f}/bbl"},
    {'label':'Price Volatility (Std Dev)','value':f"${std_all:.2f}",'note':'Monthly price dispersion, full sample'}
  ],
  'series': {
    'labels': [d.strftime('%Y-%m') for d in df['Date']],
    'price': [round(x,2) for x in df['Price']],
    'mom_pct': [None if pd.isna(x) else round(x,2) for x in df['MoM_pct']],
    'yoy_pct': [None if pd.isna(x) else round(x,2) for x in df['YoY_pct']]
  },
  'decades': decade_stats.sort_values('Decade').to_dict(orient='records'),
  'top_shocks': [
    {
      'date': r.Date.strftime('%Y-%m'),
      'price': round(r.Price,2),
      'mom_abs': round(r.MoM_abs,2),
      'mom_pct': round(r.MoM_pct,2),
      'yoy_pct': None if pd.isna(r.YoY_pct) else round(r.YoY_pct,2)
    } for r in top_shocks.itertuples(index=False)
  ],
  'stats': {
    'count': int(desc['count']), 'mean': round(desc['mean'],2), 'std': round(desc['std'],2),
    'min': round(desc['min'],2), 'p10': round(desc['10%'],2), 'p25': round(desc['25%'],2),
    'median': round(desc['50%'],2), 'p75': round(desc['75%'],2), 'p90': round(desc['90%'],2), 'max': round(desc['max'],2)
  },
  'narrative': {}
}

n = payload
n['narrative']['exec'] = (
  f"The series spans {n['meta']['rows']} monthly observations from {n['meta']['start']} to {n['meta']['end']}. "
  f"Nominal crude oil prices rise from ${n['meta']['first_price']:.2f} to ${n['meta']['last_price']:.2f}, implying a long-run CAGR of {cagr*100:.2f}% with substantial regime-dependent volatility."
)
n['narrative']['exec_bullets'] = [
  f"All-time minimum: ${overall_min:.2f}; all-time maximum: ${overall_max:.2f}; total range: ${price_range:.2f}.",
  f"Largest one-month move: ${max_mom_abs:+.2f} ({max_mom_pct:+.2f}%) in {max_mom_date.strftime('%Y-%m')}.",
  f"Highest mean price decade: {highest_decade['Decade']} (${highest_decade['mean_price']:.2f}/bbl)."
]
n['narrative']['trend'] = (
  "The full time series shows stepwise structural breaks rather than a smooth trend: a low-price pre-1973 regime, rapid escalation during 1970s oil shocks, a lower and relatively range-bound 1986–1999 period, a super-cycle rise into 2008, a post-crisis normalization, a pandemic disruption in 2020, and renewed tightening into the 2020s."
)
n['narrative']['decade'] = (
  "Decade statistics confirm regime shifts in both level and volatility. Mean prices trend materially higher in recent decades, while volatility clusters around major macro/geopolitical dislocations."
)
n['narrative']['shock'] = (
  "Shock analysis uses both month-over-month and year-over-year changes. Extreme positive and negative monthly prints are concentrated around known supply-demand discontinuities, while YoY swings capture broader cycle turning points."
)
n['narrative']['stats'] = (
  f"Distribution is positively skewed toward higher-price regimes: median (${desc['50%']:.2f}) sits below mean (${desc['mean']:.2f}), and upper-tail percentiles (P75/P90 = ${desc['75%']:.2f}/${desc['90%']:.2f}) are substantially above lower-tail levels (P10 = ${desc['10%']:.2f})."
)
n['narrative']['outlook'] = (
  "Within this dataset, the 2020s combine elevated average levels with episodic volatility, implying a higher and less stable nominal-price regime than most of the pre-2000 sample."
)
n['narrative']['outlook_bullets'] = [
  "Historical context matters: absolute price levels and variance are both regime-dependent.",
  "Shock magnitudes can reprice quickly; monthly moves alone can exceed typical annual drift.",
  "For forward analysis, pair this nominal history with inflation-adjusted and supply-balance frameworks."
]

js = "const reportData = " + json.dumps(payload) + ";\n"
with open(html_path, 'a', encoding='utf-8') as f:
    f.write(js)
