      const tr=document.createElement('tr');
      tr.innerHTML=`<td style="text-align:left;font-weight:600;">${k}</td><td>${v}</td>`;
      statsBody.appendChild(tr);
    });

    const anno = {
      id: 'annoBands',
      beforeDraw(chart) {
        const {ctx, chartArea, scales} = chart;
        if (!chartArea) return;
        const x = scales.x;
        const bands = [
          ['1973-10','1974-06','rgba(181,71,8,0.10)'],
          ['2008-01','2009-03','rgba(15,76,129,0.10)'],
          ['2020-02','2020-12','rgba(42,157,143,0.10)']
        ];
        ctx.save();
        bands.forEach(([s,e,c])=>{
          const si = d.series.labels.indexOf(s), ei = d.series.labels.indexOf(e);
          if (si<0 || ei<0) return;
          const x0 = x.getPixelForValue(si), x1 = x.getPixelForValue(ei);
          ctx.fillStyle = c;
          ctx.fillRect(Math.min(x0,x1), chartArea.top, Math.abs(x1-x0), chartArea.bottom-chartArea.top);
        });
        ctx.restore();
      }
    };

    new Chart(document.getElementById('fullTrend'), {
      type: 'line',
      data: { labels: d.series.labels, datasets: [{ label: 'Crude Oil Price ($/bbl)', data: d.series.price, borderColor: '#0f4c81', pointRadius: 0, borderWidth: 2, tension: 0.08 }] },
      options: {
        maintainAspectRatio: false,
        scales: {
          x: { grid: { color: '#eef2f7' }, ticks: { maxTicksLimit: 18 } },
          y: { grid: { color: '#e6edf5' }, title: { display:true, text:'USD per barrel' } }
        },
        plugins: { legend: { display: true } }
      },
      plugins: [anno]
    });

    new Chart(document.getElementById('decadeBars'), {
      type:'bar',
      data:{ labels:d.decades.map(x=>x.Decade), datasets:[{ label:'Mean Price ($/bbl)', data:d.decades.map(x=>x.mean_price), backgroundColor:'#2a9d8f' }] },
      options:{ maintainAspectRatio:false, scales:{ y:{ grid:{color:'#e6edf5'} } } }
    });

    new Chart(document.getElementById('momChart'), {
      type:'line',
      data:{ labels:d.series.labels, datasets:[{ label:'MoM % Change', data:d.series.mom_pct, borderColor:'#b54708', pointRadius:0, borderWidth:1.5, tension:0.05 }] },
      options:{ maintainAspectRatio:false, scales:{ x:{ ticks:{maxTicksLimit:14}}, y:{ title:{display:true,text:'Percent'}} } }
    });

    new Chart(document.getElementById('yoyChart'), {
      type:'line',
      data:{ labels:d.series.labels, datasets:[{ label:'YoY % Change', data:d.series.yoy_pct, borderColor:'#5b2a86', pointRadius:0, borderWidth:1.5, tension:0.05 }] },
      options:{ maintainAspectRatio:false, scales:{ x:{ ticks:{maxTicksLimit:14}}, y:{ title:{display:true,text:'Percent'}} } }
    });

    const prices = d.series.price;
    const min = Math.min(...prices), max = Math.max(...prices), bins = 16;
    const step = (max-min)/bins;
    const hist = Array.from({length: bins}, (_,i)=>({
      start: min + i*step,
      end: min + (i+1)*step,
      count: 0
    }));
    prices.forEach(v=>{
      let idx = Math.floor((v-min)/step);
      if (idx>=bins) idx=bins-1;
      hist[idx].count += 1;
    });

    new Chart(document.getElementById('histChart'), {
      type:'bar',
      data:{ labels:hist.map(b=>`${fmt(b.start,0)}–${fmt(b.end,0)}`), datasets:[{label:'Months', data:hist.map(b=>b.count), backgroundColor:'#0f4c81'}] },
      options:{ maintainAspectRatio:false, scales:{ x:{ ticks:{maxTicksLimit:8}}, y:{ beginAtZero:true } } }
    });
  </script>
</body>
